$users = @( @{user="shekai"; pass="BlueShekai2026!"}, @{user="staff1"; pass="BlueStaff1!"}, @{user="staff2"; pass="BlueStaff2!"} ); foreach ($u in $users) { Write-Host "Testing user: $($u.user)"; try { $session = New-Object Microsoft.PowerShell.Commands.WebRequestSession; $loginBody = @{ username = $u.user; password = $u.pass } | ConvertTo-Json; $loginRes = Invoke-RestMethod -Uri "http://localhost:3000/api/login" -Method Post -Body $loginBody -ContentType "application/json" -WebSession $session; Write-Host "Login successful"; try { $adminRes = Invoke-WebRequest -Uri "http://localhost:3000/admin-monitoring" -WebSession $session -ErrorAction Stop; Write-Host "Access /admin-monitoring: $($adminRes.StatusCode)" } catch { if ($_.Exception.Response) { Write-Host "Access /admin-monitoring: $($_.Exception.Response.StatusCode.value__)" } else { Write-Host "Access /admin-monitoring: Error" } } } catch { Write-Host "Login failed: $($_.Exception.Message)" }; Write-Host "----------------" }
